#include <bitset>
#include <sstream>
#include <iostream>

int main() {
    std::bitset<8> b;
    std::stringstream ss("10101xx");

    ss >> b; // Reads '10101', stops at 'x'

    // Read 5 bits. Bitset is 8 bits. 
    // Padding occurs: MSBs (bits 7, 6, 5) are zeroed.
    // Result: 00010101
    std::cout << b << std::endl; 

    // Failure case: reading empty or invalid data
    std::stringstream ss2(" ABC");
    std::bitset<4> b2;
    ss2 >> b2;

    if (ss2.fail()) {
        std::cerr << "Failed to read any bit (ios::failbit set)." << std::endl;
    }
}
